import {
  MeshBasicNodeMaterial,
  DirectionalLight,
  AmbientLight
} from 'three/webgpu';
import { uv, vec3, mix, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // Backdrop plane with vertical gradient (surface/ink)
  const bGeo = new ctx.THREE.PlaneGeometry(7, 6);
  const color1 = uniform(vec3(0.043, 0.043, 0.063)); // #0b0b10
  const color2 = uniform(vec3(0.086, 0.086, 0.098)); // #16161d
  const bMat = new MeshBasicNodeMaterial({
    colorNode: mix(color1, color2, uv().y)
  });
  const backdrop = new ctx.THREE.Mesh(bGeo, bMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // Load GLB model (gear-a)
  const glbPromise = ctx.glbLoader.loadGLB(config.meshUrl);

  // Storage for primitive cleanup results
  const primCleanups = [];
  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(p => {
      const result = ctx.primitives[p.name](group, p.params);
      if (result && typeof result.cleanup === 'function') {
        primCleanups.push(result.cleanup);
      }
    });
  }

  // Entrance and lighting setup after model loads
  glbPromise.then(gltf => {
    const mesh = gltf.scene;
    // Scale to fit the card tile context
    mesh.scale.set(0.5, 0.5, 0.5);
    group.add(mesh);

    // Accent rim light
    const rim = new DirectionalLight(0xff2a38, 0.8);
    rim.position.set(-1, 2, 1);
    group.add(rim);

    // Subtle ambient fill
    const fill = new AmbientLight(0x404060, 0.3);
    group.add(fill);

    // Weighted-settle entrance
    gsap.fromTo(
      group.scale,
      { x: 1.04, y: 1.04, z: 1.04 },
      { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
    );
    gsap.fromTo(
      group.position,
      { y: 0.4 },
      { y: 0, duration: 0.7, ease: 'power3.out' }
    );
  }).catch(err => {
    console.warn('GLB load failed', err);
  });

  // Event handlers
  group.userData.handlers = {
    hover: {
      enter() {
        gsap.to(group.position, {
          y: group.position.y + 0.15,
          duration: 0.3,
          ease: 'power2.out'
        });
      },
      leave() {
        gsap.to(group.position, {
          y: group.position.y - 0.15,
          duration: 0.3,
          ease: 'power2.out'
        });
      }
    },
    click() {
      ctx.emit('navigate', { to: 'hub-collection.select' });
    }
  };

  // Cleanup
  group.userData.cleanup = () => {
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);

    // Dispose GLB assets
    glbPromise.then(gltf => {
      gltf.scene.traverse(child => {
        if (child.isMesh) {
          child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach(m => m.dispose());
            } else {
              child.material.dispose();
            }
          }
        }
      });
    }).catch(() => {});

    // Cleanup primitives
    primCleanups.forEach(fn => fn());

    // Dispose backdrop
    bGeo.dispose();
    bMat.dispose();
  };

  return group;
}
